import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蛊】 巽下艮上","description":"横渠易说 - 18、【蛊】 巽下艮上","frontmatter":{"title":"18、【蛊】 巽下艮上","description":"横渠易说 - 18、【蛊】 巽下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/020.md","filePath":"zh/classics/hengqu/020.md"}'),l={name:"zh/classics/hengqu/020.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_18、【蛊】-巽下艮上" tabindex="-1">18、【蛊】 巽下艮上 <a class="header-anchor" href="#_18、【蛊】-巽下艮上" aria-label="Permalink to “18、【蛊】 巽下艮上”">​</a></h1><h3 id="彖曰-蛊-刚上而柔下-巽而止-蛊。蛊元亨而天下治也-利涉大川-往有事也。-先甲三日-后甲三日-终则有始-天行也。" tabindex="-1">彖曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也，“利涉大川”，往有事也。“先甲三日，后甲三日”，终则有始，天行也。 <a class="header-anchor" href="#彖曰-蛊-刚上而柔下-巽而止-蛊。蛊元亨而天下治也-利涉大川-往有事也。-先甲三日-后甲三日-终则有始-天行也。" aria-label="Permalink to “彖曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也，“利涉大川”，往有事也。“先甲三日，后甲三日”，终则有始，天行也。”">​</a></h3><p>忧患内萌，蛊之谓也。泰终反否，蛊之体也，弱而止，待能之时也。</p><h3 id="象曰-山下有风-蛊-君子以振民育德。" tabindex="-1">象曰：山下有风，蛊，君子以振民育德。 <a class="header-anchor" href="#象曰-山下有风-蛊-君子以振民育德。" aria-label="Permalink to “象曰：山下有风，蛊，君子以振民育德。”">​</a></h3><p>“后甲三日”，成前事之终；“先甲三日”，善后事之始也。刚上柔下，故可为之唱，是故先甲三日以蠲其法，后甲三日以重其初，明终而复始，通变不穷也。至于巽之九五，以其上下皆柔，故必无初有终，是故先庚后庚，不为物首也。于甲取应物而动，顺乎民心也。一本为事之唱。法一作治。</p><h3 id="初六-乾父之蛊-有子-考无咎。厉终吉。-象曰-乾父之蛊-意承考也。" tabindex="-1">初六，乾父之蛊，有子，考无咎。厉终吉。 象曰：“乾父之蛊”，意承考也。 <a class="header-anchor" href="#初六-乾父之蛊-有子-考无咎。厉终吉。-象曰-乾父之蛊-意承考也。" aria-label="Permalink to “初六，乾父之蛊，有子，考无咎。厉终吉。 象曰：“乾父之蛊”，意承考也。”">​</a></h3><p>处下不系应于上，如子之专制，虽意在承考，然亦危厉，以其柔巽故终吉。</p><h3 id="九二-乾母之蛊-不可贞。-象曰-乾母之蛊-得中道也。" tabindex="-1">九二，乾母之蛊，不可贞。 象曰：“乾母之蛊”，得中道也。 <a class="header-anchor" href="#九二-乾母之蛊-不可贞。-象曰-乾母之蛊-得中道也。" aria-label="Permalink to “九二，乾母之蛊，不可贞。 象曰：“乾母之蛊”，得中道也。”">​</a></h3><p>处中用巽，以刚系柔，乾母之蛊，得刚柔之中也。</p><h3 id="九三-乾父之蛊-小有悔-无大咎。-象曰-乾父之蛊-终无咎也。" tabindex="-1">九三，乾父之蛊，小有悔，无大咎。 象曰：“乾父之蛊”，终无咎也。 <a class="header-anchor" href="#九三-乾父之蛊-小有悔-无大咎。-象曰-乾父之蛊-终无咎也。" aria-label="Permalink to “九三，乾父之蛊，小有悔，无大咎。 象曰：“乾父之蛊”，终无咎也。”">​</a></h3><p>义如初六，小有悔者，以其刚也。</p><h3 id="六四-裕父之蛊-往见-吝。-象曰-裕父之蛊-往未得也。" tabindex="-1">六四，裕父之蛊，往见，吝。 象曰：“裕父之蛊”，往未得也。 <a class="header-anchor" href="#六四-裕父之蛊-往见-吝。-象曰-裕父之蛊-往未得也。" aria-label="Permalink to “六四，裕父之蛊，往见，吝。 象曰：“裕父之蛊”，往未得也。”">​</a></h3><p>“裕父之蛊”，不能为父除患，能宽裕和缓之而已。以柔居阴，失之太柔，故吝。贞固乃可乾事，以柔致远，往未得也。</p><h3 id="六五-乾父之蛊-用誉。-象曰-乾父用誉-承以德也。" tabindex="-1">六五，乾父之蛊，用誉。 象曰：“乾父用誉”，承以德也。 <a class="header-anchor" href="#六五-乾父之蛊-用誉。-象曰-乾父用誉-承以德也。" aria-label="Permalink to “六五，乾父之蛊，用誉。 象曰：“乾父用誉”，承以德也。”">​</a></h3><p>虽天子必有继也，故亦云“乾父之蛊”。</p><h3 id="上九-不事王侯-高尚其事。-象曰-不事王侯-志可则也。" tabindex="-1">上九，不事王侯，高尚其事。 象曰：“不事王侯”，志可则也。 <a class="header-anchor" href="#上九-不事王侯-高尚其事。-象曰-不事王侯-志可则也。" aria-label="Permalink to “上九，不事王侯，高尚其事。 象曰：“不事王侯”，志可则也。”">​</a></h3><p>隐居以求其志，故可则也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
